mapper.select:
SELECT COUNT(*) FROM biz_python_practice_plan p
JOIN biz_python_practice_plan_version v ON v.plan_id=p.plan_id AND v.status IN ('DRAFT','PUBLISHED')
JOIN biz_python_practice_plan_question q ON q.plan_version_id=v.plan_version_id AND q.question_id=#{questionId}
WHERE p.plan_id=#{planId}
